    for r in range(1, h - 1):
        if len(set(grid[r])) == 1:
            cue, target = grid[:r], grid[r + 1:]
            break
    else:
        for c in range(1, w - 1):
            if len({grid[r][c] for r in range(h)}) == 1:
                cue = [row[:c] for row in grid]
                target = [row[c + 1:] for row in grid]
                break
        else:
            raise ValueError('separator not found')
    shared = set(x for row in cue for x in row) & set(x for row in target for x in row)
    if len(shared) != 1:
        raise ValueError('expected one shared color')
    key = next(iter(shared))
    bg = Counter(x for row in target for x in row).most_common(1)[0][0]
    return [[3 if x != bg else key for x in row] for row in target]
